// listener attaches (the E4 boot window).
import 'dart:async';
import 'dart:convert';
import 'dart:io';

Future<void> main(List<String> args) async {
  final delay = Duration(milliseconds: int.parse(args[0]));
  final http = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
  final port = http.port;

  // Phase 1: bad-token request sent BEFORE listener attaches.
  final phase1 = WebSocket.connect('ws://127.0.0.1:$port?token=wrong')
      .then<void>((_) => 'connected?!')
      .catchError((Object e) => 'threw: ${e.runtimeType}');

  // Phase 2 started only after phase 1 settles (like the test's expectLater).
  final p1 = await phase1.timeout(const Duration(seconds: 5),
      onTimeout: () => 'BUFFERED/TIMEOUT (5s)');
  print('phase1 (delay=${delay.inMilliseconds}ms): $p1');

  // Now attach the listener (serve closure) and do the good-token handshake.
  final timer = Timer(delay, () {
    http.listen((request) async {
      final ok = request.uri.queryParameters['token'] == 'sekrit';
      if (!WebSocketTransformer.isUpgradeRequest(request) || !ok) {
        request.response.statusCode = HttpStatus.unauthorized;
        await request.response.close();
        return;
      }
      final ws = await WebSocketTransformer.upgrade(request);
      final sub = ws.listen((data) {
        final frame = jsonDecode(data as String) as Map<String, dynamic>;
        if (frame['kind'] == 'hello') {
          ws.add(jsonEncode({'kind': 'welcome'}));
        }
      });
      // hold open until client closes
      await ws.close().then((_) => sub.cancel());
    });
  });

  final phase2 = () async {
    final ws = await WebSocket.connect('ws://127.0.0.1:$port?token=sekrit');
    ws.add(jsonEncode({'kind': 'hello', 'v': 1, 'versions': [1]}));
    final first = await ws.first
        .timeout(const Duration(seconds: 3), onTimeout: () => 'WELCOME-LOST');
    await ws.close();
    return first;
  }();
  final r2 = await phase2.timeout(const Duration(seconds: 6),
      onTimeout: () => 'phase2 HANG');
  print('phase2: $r2');
  timer.cancel();
  await http.close(force: true);
}
"}

