{"content":"// Probe 2: HttpServer buffering for WS requests sent BEFORE listen attaches.
import 'dart:async';
import 'dart:convert';
import 'dart:io';

Future<void> main(List<String> args) async {
  final delay = int.parse(args[0]);
  final http = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
  final port = http.port;
  final sw = Stopwatch()..start();
  void log(String m) => print('[${sw.elapsedMilliseconds}ms] $m');

  // Phase 1: bad-token request sent BEFORE listener attaches.
  final phase1 = WebSocket.connect('ws://127.0.0.1:$port?token=wrong')
      .then<String>((_) => 'connected?!')
      .catchError((Object e) => 'threw: ${e.runtimeType}: $e');
  log('phase1 connect issued');

  Future.delayed(Duration(milliseconds: delay), () {
    log('attaching listener');
    http.listen((request) async {
      log('request: ${request.uri} token=${request.uri.queryParameters['token']}');
      final ok = request.uri.queryParameters['token'] == 'sekrit';
      if (!WebSocketTransformer.isUpgradeRequest(request) || !ok) {
        request.response.statusCode = HttpStatus.unauthorized;
        await request.response.close();
        log('-> 401 sent');
        return;
      }
      final ws = await WebSocketTransformer.upgrade(request);
      log('-> upgraded');
      ws.listen((data) {
        final frame = jsonDecode(data as String) as Map<String, dynamic>;
        log('server got: ${frame['kind']}');
        if (frame['kind'] == 'hello') {
          ws.add(jsonEncode({'kind': 'welcome'}));
        }
      }, onDone: () => log('server ws done'));
      // hold open until the client closes (like server.attach).
    });
  });

  final p1 = await phase1.timeout(
    const Duration(seconds: 4),
    onTimeout: () => 'TIMEOUT-NORESPONSE-4s',
  );
  log('phase1: $p1');

  // Phase 2: good token, like the test.
  final p2 = await () async {
    final ws = await WebSocket.connect('ws://127.0.0.1:$port?token=sekrit');
    log('phase2 ws connected');
    ws.add(jsonEncode({'kind': 'hello', 'v': 1, 'versions': [1]}));
    final first = await ws.first.timeout(
      const Duration(seconds: 3),
      onTimeout: () => 'WELCOME-LOST',
    );
    await ws.close();
    return 'phase2 first frame: $first';
  }().timeout(const Duration(seconds: 8), onTimeout: () => 'phase2 HANG');
  log(p2);
  await http.close(force: true);
}
