    var subscription = _subscription = stream.listen(
      (data) {
        _controller!.add(data);
      },
      onDone: _done,
      onError: _done,
      cancelOnError: true,
    );
    if (_issuedPause) {
      subscription.pause();
      _issuedPause = false;
    }
    return completer.future;
