/// THROWAWAY stress harness for the E4 flake (gh-1360) — NOT for commit.
///
/// Replicates test/integration/wire_serve_cli_test.dart's E4 body N times
/// in ONE process (mirrors CI where the whole wire file ran in the same
/// isolate before E4), with per-phase timings + full onDiagnostic capture
/// on a welcome-timeout.
library;

import 'dart:async';
import 'dart:convert';
import 'dart:io' show WebSocket, stderr;

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import '../../bin/fah_wire_serve.dart';
import '../cli/agent_cli_test_support.dart';

void main() {
  test('E4 STRESS x iterations', () async {
    const iterations = 30;
    final failures = <int>[];
    for (var i = 1; i <= iterations; i++) {
      final ok = await _one(i);
      if (!ok) failures.add(i);
    }
    expect(failures, isEmpty, reason: 'failed iterations: $failures');
  }, timeout: const Timeout(Duration(minutes: 20)));
}

Future<bool> _one(int i) async {
  final sw = Stopwatch()..start();
  final diagnostics = <String>[];
  void diag(String m) => diagnostics.add('[${sw.elapsedMilliseconds}ms] $m');
  final env = MemoryExecutionEnv(cwd: '/work/stress$i');
  final fake = FakeStreamFunction([textTurn('shh')]);
  final cli = AgentCli(
    config: AgentCliConfig(
      model: testModel,
      apiKey: 'sekrit-token',
      env: env,
      sessionRoot: '/sessions$i',
      webSearchConfig: WebSearchConfig(),
      providerKind: 'openai-completions',
      approvalMode: ApprovalMode.yolo,
    ),
    io: FakeCliIO()..isInteractive = false,
    streamFunction: fake.call,
  );
  final http = await bindLoopback(0);
  final served = cli.runWireServe(
    serve: (server) => httpListen(http, server, 'sekrit-token'),
    onDiagnostic: (line) => diag(line),
  );

  // Phase 1: bad token.
  final p1 = Stopwatch()..start();
  var p1ok = false;
  try {
    await WebSocket.connect('ws://127.0.0.1:${http.port}?token=wrong')
        .then<void>((_) {})
        .timeout(const Duration(seconds: 10));
    diag('P1: did NOT throw (BUG)');
  } on TimeoutException {
    diag('P1: TIMEOUT (server never answered the bad token in 10s)');
  } on Object catch (e) {
    p1ok = true;
    diag('P1 ok (${p1.elapsedMilliseconds}ms): ${e.runtimeType}');
  }

  // Phase 2: good token with per-attempt logging.
  WebSocket? ws;
  final p2 = Stopwatch()..start();
  for (var attempt = 1; attempt <= 200; attempt++) {
    try {
      ws = await WebSocket.connect(
        'ws://127.0.0.1:${http.port}?token=sekrit-token',
      );
      diag('P2 connect ok on attempt $attempt (${p2.elapsedMilliseconds}ms)');
      break;
    } on Object catch (e) {
      diag('P2 attempt $attempt threw (${p2.elapsedMilliseconds}ms): $e');
      await Future<void>.delayed(const Duration(milliseconds: 5));
    }
  }
  if (ws == null) {
    diag('P2: never connected');
    await _dump(i, diagnostics, served, http, 'P2 never connected');
    return false;
  }

  ws.add(jsonEncode({
    'v': 1,
    'kind': 'hello',
    'versions': [1],
  }));
  final kinds = <String>[];
  Object? firstFrame;
  try {
    await for (final message in ws) {
      final kind =
          (jsonDecode(message as String) as Map<String, dynamic>)['kind'];
      kinds.add('$kind');
      diag('P3 frame: $kind');
      firstFrame = kind;
      break;
    }
  } on TimeoutException {
    // ignore below
  }
  final frame = await (() => Future.value(firstFrame))
      .timeout(const Duration(seconds: 10), onTimeout: () => 'LOST');
  if (frame == 'LOST' || firstFrame != 'welcome') {
    diag('P3: welcome LOST (got=$kinds) — DUMPING DIAGNOSTICS');
    await _dump(i, diagnostics, served, http, 'welcome lost');
    return false;
  }
  diag('P3 welcome arrived (${sw.elapsedMilliseconds}ms total)');
  await ws.close();
  await http.close(force: true);
  await served.timeout(const Duration(seconds: 20));
  return p1ok;
}

Future<void> _dump(
  int i,
  List<String> diagnostics,
  Future<int> served,
  HttpServer http,
  String why,
) async {
  stderr.writeln('=== iteration $i FAILED: $why ===');
  for (final d in diagnostics) {
    stderr.writeln(d);
  }
  await http.close(force: true);
  await served.timeout(const Duration(seconds: 5), onTimeout: () => -1);
}
