/// Awaits the first WS frame on [ws] for up to 10s, recording every frame
/// kind in [seen]. Unlike `ws.first` (which cancels after one event and
/// cannot distinguish "slow" from "never"), the listener stays attached —
/// the gh-1360 wedge shows up as a timeout with an EMPTY [seen] — and
/// stream end/error resolve to null instead of hanging the await.
Future<Object?> _awaitFirstFrame(WebSocket ws, List<String> seen) {
  final got = Completer<Object?>();
  ws.listen(
    (message) {
      seen.add(decodeLine(message as String)['kind'] as String);
      if (!got.isCompleted) got.complete(message);
    },
    onDone: () {
      if (!got.isCompleted) got.complete(null);
    },
    onError: (Object error) {
      if (!got.isCompleted) got.complete(null);
    },
  );
  return got.future.timeout(
    const Duration(seconds: 10),
    onTimeout: () => null,
  );
}

