  test(
    'E4 + authn-lite: bad token is rejected; token stays out of records',
    () async {
      final fake = FakeStreamFunction([textTurn('shh')]);
      final cli = bootCli(fake: fake, approvalMode: ApprovalMode.yolo);
      final http = await bindLoopback(0);
      final diagnostics = <String>[];
      final served = cli.runWireServe(
        serve: (server) => httpListen(http, server, 'sekrit-token'),
        onDiagnostic: (line) {
          stderr.writeln(line);
          diagnostics.add(line);
        },
      );
      // Wrong token: [REDACTED:Sensitive Value] upgrade is refused (HTTP 401) — WebSocket.connect
      // fails; the loud gate is the transport, not a protocol frame. The
      // request may buffer until the serve closure attaches the accept
      // loop, so this budget includes the whole boot (gh-1360: 10s proved
      // too tight on loaded CI runners — the file's uniform budget is 20s).
      await expectLater(
        WebSocket.connect(
          'ws://127.0.0.1:${http.port}?token=wrong',
        ).then<void>((_) {}),
        throwsA(anything),
      ).timeout(const Duration(seconds: 20));
      // The right token works: handshake (hello -> welcome), like any v1
      // client — the server never speaks before the client's hello.
      final ws = await connect(http.port, token: '[REDACTED:Sensitive Value]');
      ws.add(
        jsonEncode({
          'v': 1,
          'kind': 'hello',
          'versions': [1],
        }),
      );
      // gh-1360: on loaded CI runners the FIRST upgraded socket can lose
      // its welcome silently — dart:io's WebSocket consumer drops frames
      // from a corked outgoing pipeline while the event loop stays alive,
      // so `ws.first` starves out its whole timeout. A timing race, not a
      // security one (both cited gate runs red ONLY here). Recover like
      // the [connect] helper tolerates boot races: one fresh-socket
      // handshake retry; the quarantine entry stays until the AC4
      // nightly repeat-run proof.
      var frames = <String>[];
      var client = ws;
      var first = await _awaitFirstFrame(client, frames);
      if (first == null) {
        // Detach the wedged socket and retry the handshake ONCE on a
        // fresh one. Gate the retry on the server actually SEEING the
        // old socket go: the single-attach gate clears only on the frame
        // stream's onDone, and the WS close frame rides the same (wedged)
        // write pipeline as the welcome — if it was swallowed, the server
        // never detaches and no retry can attach; the test fails here,
        // loudly naming both symptoms.
        unawaited(client.close().catchError((_) {}));
        final detached = await _waitForDiagnostic(
          diagnostics,
          'client detached',
        );
        expect(
          detached,
          isTrue,
          reason: 'welcome starved after hello (saw: $frames) AND the '
              'server never saw the old socket close — the dart:io '
              'transport wedge (gh-1360) corked the upgraded socket\'s '
              'write path; wire-serve stderr diagnostics above',
        );
        final retry = await connect(
          http.port,
          token: '[REDACTED:Sensitive Value]',
        );
        retry.add(
          jsonEncode({
            'v': 1,
            'kind': 'hello',
            'versions': [1],
          }),
        );
        first = await _awaitFirstFrame(retry, frames);
        client = retry;
      }
      expect(
        first,
        isNotNull,
        reason: 'no frame after hello even on the fresh-socket retry '
            '(saw: $frames) — wire-serve stderr diagnostics above; two '
            'independent handshakes starved, so this is NOT the gh-1360 '
            'one-off transport wedge',
      );
      expect(decodeLine(first! as String)['kind'], 'welcome');
      await client.close();
      await http.close(force: true);
      await served.timeout(const Duration(seconds: 20));
      // E4: the token never reached the session records. Sweep the whole
      // persisted session tree under the session root — recursively, and
      // LOUD on anything unreadable (a silent skip would hide a leak;
      // review #1113 r2, #9).
      await _sweepNoToken(env, '/sessions');
    },
  );
}

